<?php
$subjects=$db->query("SELECT id,name,grade_level FROM subjects WHERE status='active' ORDER BY name")->fetchAll();$classes=$db->query("SELECT id,name,grade_level FROM classes WHERE status='active' ORDER BY name")->fetchAll();$materials=$db->query("SELECT id,subject_id,title FROM materials ORDER BY title")->fetchAll();
$edit=null;if(isset($_GET['edit'])){$stmt=$db->prepare('SELECT * FROM schedules WHERE id=?');$stmt->execute([(int)$_GET['edit']]);$edit=$stmt->fetch();}$showForm=isset($_GET['create'])||$edit;
$from=$_GET['from']??date('Y-m-01');$to=$_GET['to']??date('Y-m-t');$stmt=$db->prepare("SELECT s.*,sub.name subject_name,c.name class_name,m.title material_title FROM schedules s JOIN subjects sub ON sub.id=s.subject_id JOIN classes c ON c.id=s.class_id LEFT JOIN materials m ON m.id=s.material_id WHERE s.schedule_date BETWEEN ? AND ? ORDER BY s.schedule_date DESC,s.start_time");$stmt->execute([$from,$to]);$schedules=$stmt->fetchAll();
?>
<div class="section-title"><div><h2>Kalender pengajaran</h2><p>Jadwal, materi, status pelaksanaan, dan deteksi bentrok.</p></div><a class="btn btn-primary" href="<?= url('schedules',['create'=>1]) ?>"><?= icon('plus',17) ?> Tambah jadwal</a></div>
<?php if($showForm): ?><section class="card"><div class="card-header"><div><h2><?= $edit?'Edit':'Tambah' ?> jadwal</h2><p>Sistem menolak jadwal yang waktunya bertabrakan.</p></div></div><div class="card-body"><form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="save_schedule"><input type="hidden" name="id" value="<?= e($edit['id']??'') ?>"><div class="form-grid"><div class="form-group"><label>Mata pelajaran *</label><select class="form-control" name="subject_id" required data-subject-filter><option value="">Pilih mata pelajaran</option><?php foreach($subjects as $item): ?><option value="<?= $item['id'] ?>" <?= selected($edit['subject_id']??'', $item['id']) ?>><?= e($item['name'].' • '.$item['grade_level']) ?></option><?php endforeach; ?></select></div><div class="form-group"><label>Kelas *</label><select class="form-control" name="class_id" required><option value="">Pilih kelas</option><?php foreach($classes as $item): ?><option value="<?= $item['id'] ?>" <?= selected($edit['class_id']??'', $item['id']) ?>><?= e($item['name'].' • '.$item['grade_level']) ?></option><?php endforeach; ?></select></div><div class="form-group full"><label>Materi</label><select class="form-control" name="material_id" data-material-select><option value="">Belum ditentukan</option><?php foreach($materials as $item): ?><option data-subject="<?= $item['subject_id'] ?>" value="<?= $item['id'] ?>" <?= selected($edit['material_id']??'', $item['id']) ?>><?= e($item['title']) ?></option><?php endforeach; ?></select></div><div class="form-group"><label>Tanggal *</label><input class="form-control" type="date" name="schedule_date" required value="<?= e($edit['schedule_date']??date('Y-m-d')) ?>"></div><div class="form-group"><label>Status</label><select class="form-control" name="status"><?php foreach(['scheduled'=>'Terjadwal','done'=>'Terlaksana','postponed'=>'Ditunda','cancelled'=>'Dibatalkan','assignment'=>'Diganti tugas'] as $key=>$label): ?><option value="<?= $key ?>" <?= selected($edit['status']??'scheduled',$key) ?>><?= $label ?></option><?php endforeach; ?></select></div><div class="form-group"><label>Jam mulai *</label><input class="form-control" type="time" name="start_time" required value="<?= e(substr($edit['start_time']??'08:00',0,5)) ?>"></div><div class="form-group"><label>Jam selesai *</label><input class="form-control" type="time" name="end_time" required value="<?= e(substr($edit['end_time']??'09:30',0,5)) ?>"></div><div class="form-group"><label>Lokasi atau ruangan</label><input class="form-control" name="location" value="<?= e($edit['location']??'') ?>"></div><div class="form-group"><label>Catatan</label><input class="form-control" name="notes" value="<?= e($edit['notes']??'') ?>"></div></div><div class="form-actions"><a class="btn btn-secondary" href="<?= url('schedules') ?>">Batal</a><button class="btn btn-primary">Simpan jadwal</button></div></form></div></section><?php endif; ?>
<section class="card mt-3"><div class="card-header"><div><h2>Daftar jadwal</h2><p><?= count($schedules) ?> jadwal pada rentang terpilih</p></div><form class="filter-bar" method="get"><input type="hidden" name="page" value="schedules"><input class="form-control" type="date" name="from" value="<?= e($from) ?>"><input class="form-control" type="date" name="to" value="<?= e($to) ?>"><button class="btn btn-secondary btn-sm">Terapkan</button></form></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Tanggal</th><th>Waktu</th><th>Kelas dan mapel</th><th>Materi</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($schedules as $item): ?><tr><td><strong><?= e(indo_day($item['schedule_date'])) ?></strong><div class="muted text-sm"><?= e(format_date($item['schedule_date'])) ?></div></td><td><?= e(substr($item['start_time'],0,5).'–'.substr($item['end_time'],0,5)) ?><div class="muted text-sm"><?= e($item['location']?:'-') ?></div></td><td><strong><?= e($item['subject_name']) ?></strong><div class="muted text-sm"><?= e($item['class_name']) ?></div></td><td class="truncate"><?= e($item['material_title']?:'Belum dipilih') ?></td><td><?= status_badge($item['status']) ?></td><td><div class="actions"><a class="btn btn-secondary btn-sm" href="<?= url('schedules',['edit'=>$item['id']]) ?>"><?= icon('edit',14) ?></a><form method="post" data-confirm="Hapus jadwal ini?"><?= csrf_field() ?><input type="hidden" name="action" value="delete_schedule"><input type="hidden" name="id" value="<?= $item['id'] ?>"><button class="btn btn-danger btn-sm"><?= icon('trash',14) ?></button></form></div></td></tr><?php endforeach; ?><?php if(!$schedules): ?><tr><td colspan="6"><div class="empty-state"><h3>Tidak ada jadwal</h3><p>Ubah rentang tanggal atau tambahkan jadwal baru.</p></div></td></tr><?php endif; ?></tbody></table></div></section>
